window.kbPageData["views/entry/k-a31a4da1a5c0ccfe"] = {"key":"entry/k-a31a4da1a5c0ccfe","state":{"route":"entry/k-a31a4da1a5c0ccfe"},"node":{"id":"k-a31a4da1a5c0ccfe","mode":"k","title":"十四个坚持","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["modern"],"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"1.坚持党对一切工作的领导。党政军民学，东西南北中，党是领导一切的。\n2.坚持以人民为中心。人民是历史的创造者，是决定党和国家前途命运的根本力量。\n3.坚持全面深化改革。只有社会主义才能救中国，只有改革开放才能发展中国、发展社\n会主义、发展马克思主义。\n4.坚持新发展理念。发展是解决我国一切问题的基…","sources":[{"id":"b15007b5024adbae","label":"十四个坚持","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.坚持党对一切工作的领导。党政军民学，东西南北中，党是领导一切的。\n2.坚持以人民为中心。人民是历史的创造者，是决定党和国家前途命运的根本力量。\n3.坚持全面深化改革。只有社会主义才能救中国，只有改革开放才能发展中国、发展社\n会主义、发展马克思主义。\n4.坚持新发展理念。发展是解决我国一切问题的基础和关键，发展必须是科学发展，必\n须坚定不移贯彻创新、协调、绿色、开放、共享的发展理念。\n5.坚持人民当家作主。坚持党的领导、人民当家作主、依法治国有机统一是社会主义政\n治发展的必然要求。\n6.坚持全面依法治国。全面依法治国是中国特色社会主义的本质要求和重要保障。\n7.坚持社会主义核心价值体系。文化自信是一个国家、一个民族发展中更基本、更深沉、\n更持久的力量。\n8.坚持在发展中保障和改善民生。增进民生福祉是发展的根本目的。\n9.坚持人与自然和谐共生。建设生态文明是中华民族永续发展的千年大计。\n10.坚持总体国家安全观。统筹发展和安全，增强忧患意识，做到居安思危，是我们党\n治国理政的一个重大原则。\n11.坚持党对人民军队的绝对领导。建设一支听党指挥、能打胜仗、作风优良的人民军\n队，是实现“两个一百年”奋斗目标、实现中华民族伟大复兴的战略支撑。\n12.坚持“一国两制”和推进祖国统一。保持香港、澳门长期繁荣稳定，实现祖国完全\n统一，是实现中华民族伟大复兴的必然要求。\n13.坚持推动构建人类命运共同体。中国人民的梦想同各国人民的梦想息息相通，实现\n中国梦离不开和平的国际环境和稳定的国际秩序。\n14.坚持全面从严治党。勇于自我革命，从严管党治党，是我们党最鲜明的品格。","source":{"doc":"3ccc56f4000d1642c2d1","first":16,"last":17,"page":16,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-a31a4da1a5c0ccfe":[]}};
